begin;
set local search_path=public,extensions;
do $import$
declare r jsonb; org uuid; facility uuid; listing uuid;
begin
for r in select value from jsonb_array_elements('[{"external_id":"NCT05768139:01f0493fb749ab0281fb","title":"First-in-Human Study of Tersolisib (STX-478) as Monotherapy and in Combination With Other Antineoplastic Agents in Participants With Advanced Solid Tumors","sponsor":"Eli Lilly and Company","source_url":"https://clinicaltrials.gov/study/NCT05768139","facility":"Winship Cancer Institute, Emory University","address":"Atlanta, Georgia, 30322","lat":33.749,"lon":-84.38798,"minimum_age":18,"maximum_age":null,"requirements":"Published sex requirement: ALL\n\nKey Inclusion Criteria:\n\n* Has an advanced or refractory solid tumor malignancy that is metastatic or locally advanced and unresectable (as specified by Cohort)\n* Has a new or recent tumor biopsy (collected at screening, if feasible) or will provide an adequate tissue sample prior to screening\n* Has a tumor that harbors a documented PI3Kα mutation (cohort specific criterion for cohort-specific mutation types)\n* Is ≥18 years of age at the time of signing the ICF\n* Has an ECOG performance status score of 0 or 1 at screening\n* Has adequate organ function as defined per protocol\n\nKey Exclusion Criteria:\n\n* Has history (within ≤2 years before screening) of a solid tumor or hematological malignancy that is histologically distinct from the cancers being studied\n* Has symptomatic brain or spinal metastases\n* Has an established diagnosis of uncontrolled diabetes mellitus (defined as HbA1c ≥8% and/or FBG ≥140 mg/dL \\[7.7 mmol/L\\] and/or requiring or required insulin).\n* Has had prior treatment with PI3K/AKT/mTOR inhibitor(s), except in certain circumstances\n* Has had treatment with any local or systemic antineoplastic therapy or investigational anticancer agent within 14 days or 4 half-lives, whichever is longer, prior to the initiation of study treatment up to a maximum washout period of 28 days. Endocrine therapy does not require a washout period if the patient is enrolling in a cohort with the same combination endocrine therapy.\n* Has toxicities from previous anticancer therapies that have not resolved to baseline levels or CTCAE grade ≤1, with the exception of alopecia and peripheral neuropathy.\n* Has had radiotherapy within 14 days before the initiation of study treatment"},{"external_id":"NCT05243966:d5106522c5a34f2597c9","title":"Myriad™ Augmented Soft Tissue Reconstruction Registry","sponsor":"Aroa Biosurgery Limited","source_url":"https://clinicaltrials.gov/study/NCT05243966","facility":"Northeast Georgia Medical Center, Inc.","address":"Gainesville, Georgia, 30501","lat":34.29788,"lon":-83.82407,"minimum_age":18,"maximum_age":null,"requirements":"Published sex requirement: ALL\n\nInclusion Criteria:\n\n* Willing and able to provide written informed consent and to comply with the requirements of Clinical Investigational Plan\n* Male or female patients aged 18 years or above\n* Patients where Matrix and/or Morcells were used as part of their soft tissue reconstruction procedure\n* Subject that are willing and able to comply with all aspects of the treatment and evaluation schedule\n\nExclusion Criteria:\n\n* Patients with known sensitivity to ovine (sheep) derived material\n* Patients with full thickness (''third degree'') burns\n* Patients with wounds with uncontrolled clinical infection (CDC Contamination Grade=4)\n* Any medical condition or serious intercurrent illness that, in the opinion of the investigator, may make it undesirable for the patient to participate in the study\n* Patient is currently participating or has participated in another clinical study within past 30 days prior to enrollment\n* Pregnant or lactating women\n* Any subject who, at the discretion of the Investigator, is not suitable for inclusion in the study"},{"external_id":"NCT07431281:2be800f0eaa22210a8c3","title":"Sonesitatug Vedotin in Combination With Capecitabine With or Without Rilvegostomig in Participants With Advanced or Metastatic Gastric, Gastroesophageal Junction, or Esophageal Adenocarcinoma Expressing Claudin18.2","sponsor":"AstraZeneca","source_url":"https://clinicaltrials.gov/study/NCT07431281","facility":"Research Site","address":"Atlanta, Georgia, 30309","lat":33.749,"lon":-84.38798,"minimum_age":18,"maximum_age":null,"requirements":"Published sex requirement: ALL\n\nInclusion Criteria:\n\n* Capable of giving signed informed consent\n* Participant must be 18 years or the legal age of consent in the jurisdiction in which the study is taking place, at the time of signing the informed consent.\n* Previously untreated histologically documented unresectable, locally advanced, or metastatic gastric, GEJ, or distal esophagus (distal third of the esophagus) adenocarcinoma\n* Positive CLDN18.2 expression, as determined prospectively by central IHC testing\n* Confirmed PD-L1 CPS status by central IHC testing and ICI eligibility per investigator judgement is required to determine cohort eligibility as described below:\n\n  1. Cohort 1: PD-L1 positive as determined by central IHC testing and the participant is deemed ICI eligible per investigator judgement.\n  2. Cohort 2: PD-L1 negative as determined by central IHC testing OR the participant is ICI ineligible\n* ECOG performance status of 0 or 1 with no deterioration to \\> 1 over the previous 2 weeks prior to baseline at screening and prior to randomisation.\n* Minimum life expectancy of ≥ 12 weeks.\n* At least one lesion (measurable and/or non-measurable) that can be accurately assessed by the investigator based on RECIST 1.1.\n* Adequate organ and bone marrow function as specified in the protocol\n* Body weight ≥ 35 kg.\n* Sex and contraceptive requirements\n\nExclusion Criteria:\n\n* Known HER2-positive status\n* Significant or unstable gastric bleeding and/or untreated gastric ulcers.\n* Active or history of autoimmune or inflammatory disorders requiring systemic treatment with steroids or other immunosuppressive treatment or assessed by investigator as not appropriate to participate due to undue risk are excluded.\n* CNS pathology\n* Clinically significant pleural effusions or ascites and/or pleural effusions or ascites that require drainage, peritoneal shunt, or indwelling catheter/drain.\n* Require parenteral nutrition support due to gastric or gastrointestinal obstruction.\n* Peripheral neuropathy, sensory or motor, ≥ CTCAE Grade 2 at screening.\n* Persistent toxicities caused by previous anticancer therapy excluding alopecia, not yet improved to Grade ≤ 1 or baseline.\n* Cardiac abnormalities as outlined in the protocol\n* Uncontrolled diabetes or diabetic neuropathy within 3 months prior to randomisation.\n* Infectious disease including active hepatitis A infection; uncontrolled hepatitis B and/or chronic or active hepatitis B with HBV DNA ≥ 100 IU/mL; Known chronic, active, or uncontrolled hepatitis C; HIV infection that is not well controlled\n* Known partial or total DPD enzyme deficiency"},{"external_id":"NCT05812807:72392785e862be547fb3","title":"Pembrolizumab vs. Observation in People With Triple-negative Breast Cancer Who Had a Pathologic Complete Response After Chemotherapy Plus Pembrolizumab","sponsor":"Alliance for Clinical Trials in Oncology","source_url":"https://clinicaltrials.gov/study/NCT05812807","facility":"Grady Health System","address":"Atlanta, Georgia, 30303","lat":33.749,"lon":-84.38798,"minimum_age":18,"maximum_age":null,"requirements":"Published sex requirement: ALL\n\nInclusion Criteria:\n\n* Age \\>= 18 years\n* Eastern Cooperative Oncology Group (ECOG) Performance Status 0-2\n* Triple Negative Breast Cancer:\n\n  * Patients with a history of clinical stage T1cN1-2 or T2-4N0-2 (clinical stage II or III prior to preoperative therapy) breast cancer at time of diagnosis according to the primary tumor-regional lymph node anatomic staging criteria of the American Joint Committee on Cancer (AJCC), 8th edition as determined by the investigator in radiologic assessment, clinical assessment or both\n  * Patients must have no residual invasive disease in the breast or lymph nodes after the completion of neoadjuvant therapy. Residual ductal carcinoma in situ (DCIS) is allowed. Isolated tumor cells are considered node-negative\n  * Estrogen receptor (ER) and progesterone receptor (PR) =\\< 10%; HER2-negative by American Society of Clinical Oncology (ASCO)/College of American Pathologists (CAP) guidelines (immunohistochemistry \\[IHC\\] and fluorescence in situ hybridization \\[FISH\\])\n  * If invasive disease was present in both breasts, participation in the study is permitted as long as the eligibility criteria are met for both tumors/breasts\n* Patients must have received neoadjuvant chemotherapy in combination with pembrolizumab for a minimum of 6 cycles. All systemic chemotherapy must have been completed preoperatively\n* An interval of no more than 12 weeks between the completion date of the final surgery and the date of randomization\n\n  \\* Note: Adjuvant radiation can be given on study, however, it is recommended to complete adjuvant radiation prior to registration. If radiation is given on study, it is encouraged to be given concurrently with pembrolizumab if the patient is on the pembrolizumab arm, per investigator discretion. Treatment with adjuvant pembrolizumab is strongly discouraged prior to participation in this trial, but if administered (e.g., if patients are awaiting pathology results), pembrolizumab may be administered for up to 6 weeks (i.e., up to 2 q3week doses or up to one q6week dose) post-surgery and must be completed prior to registration post-surgery and must be completed prior to registration\n* Use of investigational anti-cancer agents must be discontinued at time of registration\n* Adequate excision: Surgical removal of all clinically evident disease in the breast and lymph nodes as follows:\n\n  * Breast surgery: Total mastectomy or breast-conserving surgery with histologically negative margins, including no ink on tumor for DCIS, at the time of excision\n\n    \\*\\* For patients who undergo breast-conserving surgery, the margins of the resected specimen must be histologically free of ductal carcinoma in-situ (DCIS) as determined by the local pathologist. If pathologic examination demonstrates DCIS at the line of resection, additional operative procedures may be performed to obtain clear margins. If DCIS is still present at the resected margin after re-excision(s), the patient must undergo total mastectomy to be eligible. Patients with margins positive for classic lobular carcinoma in situ (LCIS) are eligible without additional resection\n  * Lymph node surgery:\n\n    * For a patient with clinically N0 disease, a sentinel lymph node biopsy should have been performed at time of surgical evaluation, and if pathologically node positive, the patient is no longer eligible. Isolated tumor cells are considered node-negative\n    * For a patient with clinically N1 disease at diagnosis (with positive results from a fine-needle aspiration, core biopsy, or sentinel node biopsy performed prior to preoperative therapy) additional surgical evaluation of the axilla following preoperative therapy is required\n\n      \\*\\*\\* If they become cN0 (no palpable adenopathy), then a sentinel lymph node biopsy could have been performed at time of surgery (axillary dissection would also be permitted); if the sentinel lymph node biopsy is positive, the patient is no longer eligible\n    * If sentinel node biopsy performed before preoperative therapy was negative, no additional surgical evaluation of the axilla is required after preoperative therapy. If sentinel node biopsy performed before preoperative therapy was positive, an ALND is required after preoperative therapy\n    * If the only sentinel node identified by isotope scan is in the internal mammary chain, surgical evaluation of the axilla is still required\n    * If sentinel node evaluation after preoperative therapy is negative, no further additional surgical evaluation of the axilla is required\n    * Axillary dissection without sentinel node evaluation is permitted as the initial or sole axillary evaluation after preoperative therapy\n* If breast-conserving surgery was performed but patient will not be receiving breast radiation, the patient is not eligible\n* Not pregnant and not nursing, because this study involves an agent whose genotoxic, mutagenic and teratogenic effects on the developing fetus and newborn are unknown. Therefore, for women of childbearing potential only, a negative serum or urine pregnancy test done =\\< 7 days prior to randomization is required\n* Absolute neutrophil count (ANC) \\>= 1,000/mm\\^3\n* Platelet Count \\>= 100,000/mm\\^3\n* Estimated glomerular filtration rate (eGFR) \\>= 15 mL/min/1.73m\\^2\n* Total Bilirubin =\\<1.5 x upper limit of normal (ULN)\n\n  \\* Patients with Gilbert''s disease with a total bilirubin =\\< 2.5 x ULN and direct bilirubin within normal limits are permitted\n* Aspartate aminotransferase (AST) serum aspartate aminotransferase \\[SGOT\\] / alanine aminotransferase (ALT) serum glutamic pyruvic transaminase \\[SGPT\\] =\\< 3 x institutional ULN\n* Patients must be willing to provide tumor tissue from the diagnostic core biopsy. If inadequate tumor tissue is available, patients are still eligible to participate in the trial\n* Patients with a prior or concurrent malignancy whose natural history or treatment does not have the potential to interfere with the safety or efficacy assessment of the investigational regimen are eligible for this trial\n* Patients with known history or current symptoms of cardiac disease, or history of treatment with cardiotoxic agents, should have a clinical risk assessment of cardiac function using the New York Heart Association Functional Classification. To be eligible for this trial, patients should be class 2B or better\n* Patients with known HIV infection who are on effective anti-retroviral therapy with undetectable viral load within 6 months prior to registration are eligible for this trial\n\nExclusion Criteria:\n\n* No stage IV (metastatic) breast cancer\n* No history of any prior (ipsi- or contralateral) invasive breast cancer. Prior DCIS is allowed\n* No evidence of recurrent disease following preoperative therapy and surgery\n* No known active liver disease, e.g. due to hepatitis B virus (HBV), hepatitis C virus (HCV), autoimmune hepatic disorders, or sclerosing cholangitis\n* No history of intolerance, including Grade 3 or 4 infusion reaction or hypersensitivity to pembrolizumab or murine proteins or any components of the product\n\n  \\* Note: Prior immune-related adverse events (irAEs) are allowed if they resolved to ≤ grade 1 and the patient tolerated subsequent therapy without requiring chronic steroids for the irAE. The following are exceptions to this criterion: Grade 2 or lower immune mediated endocrinopathies due to neoadjuvant checkpoint inhibition but patients are stable on endocrine therapy and were able to continue checkpoint inhibition.\n* No medical conditions that require chronic systemic steroids (\\>10 mg prednisone daily or equivalent) or any other form of immunosuppressive medications and has required such therapy in the last two years. Replacement therapy (e.g. thyroxine, insulin, or physiologic corticosteroid replacement therapy for adrenal or pituitary insufficiency, etc.) is not considered a form of systemic therapy\n* Patients who are unable or unwilling to comply with the requirements of the protocol per investigator assessment are not eligible"},{"external_id":"NCT05812807:f37652aea418b71ba43a","title":"Pembrolizumab vs. Observation in People With Triple-negative Breast Cancer Who Had a Pathologic Complete Response After Chemotherapy Plus Pembrolizumab","sponsor":"Alliance for Clinical Trials in Oncology","source_url":"https://clinicaltrials.gov/study/NCT05812807","facility":"Emory University Hospital Midtown","address":"Atlanta, Georgia, 30308","lat":33.749,"lon":-84.38798